async def test_AC10_8_3_reconciliation_run_audit_checkpoints(db, test_user: User, monkeypatch: pytest.MonkeyPatch) -> None:
    'AC-observability.8.3'; statement, _ = await _seed_router_txns(db, test_user, count=1); statement_id = statement.id
    async def fake_execute_matching(*_args, **_kwargs): return [ReconciliationMatch(atomic_txn_id=uuid4(), journal_entry_ids=[], match_score=90, score_breakdown={}, status=ReconciliationStatus.AUTO_ACCEPTED)]
    mock_info = MagicMock(); mock_exception = MagicMock(); monkeypatch.setattr(reconciliation_router, 'execute_matching', fake_execute_matching); monkeypatch.setattr(reconciliation_router.logger, 'info', mock_info); monkeypatch.setattr(reconciliation_router.logger, 'exception', mock_exception); response = await reconciliation_router.run_reconciliation(ReconciliationRunRequest(statement_id=statement_id, limit=25), db=db, user_id=test_user.id); calls = [(call.args[0], call.kwargs) for call in mock_info.call_args_list]; started = next((kwargs for event_name, kwargs in calls if event_name == 'reconciliation.run.started')); completed = next((kwargs for event_name, kwargs in calls if event_name == 'reconciliation.run.completed')); assert response.matches_created == 1; assert started['audit_event'] == 'reconciliation.run.started'; assert started['request_id']; assert started['statement_id'] == str(statement_id); assert started['phase'] == 'matching_started'; assert started['limit'] == 25; assert completed['audit_event'] == 'reconciliation.run.completed'; assert completed['request_id'] == started['request_id']; assert completed['matches_created'] == 1; assert completed['auto_accepted'] == 1; assert completed['pending_review'] == 0; assert completed['unmatched'] == 1
    async def fail_execute_matching(*_args, **_kwargs): raise RuntimeError('matching score service unavailable with raw details omitted')
    monkeypatch.setattr(reconciliation_router, 'execute_matching', fail_execute_matching)
    with pytest.raises(RuntimeError, match='matching score service unavailable'): await reconciliation_router.run_reconciliation(ReconciliationRunRequest(statement_id=statement_id, limit=25), db=db, user_id=test_user.id)
    failed = next((call.kwargs for call in mock_exception.call_args_list if call.args[0] == 'reconciliation.run.failed')); assert failed['audit_event'] == 'reconciliation.run.failed'; assert failed['statement_id'] == str(statement_id); assert failed['phase'] == 'matching_failed'; assert failed['error_type'] == 'RuntimeError'
