async def test_accept_reject_batch_accept(db, test_user: User) -> None:
    'AC-reconciliation.review-queue.2 AC4.3.3'; account, statement, txn1, expense = await _seed_expense_setup(db, test_user); txn2 = create_test_transaction(db, statement, amount=Decimal('8.00')); txn3 = create_test_transaction(db, statement, amount=Decimal('9.00')); db.add_all([txn2, txn3]); await db.flush()
    e1 = await create_anchored_match_entry(db, user_id=test_user.id, bank_account=account, counter_account=expense, entry_date=txn1.txn_date, memo='Accept', amount=txn1.amount); e2 = await create_anchored_match_entry(db, user_id=test_user.id, bank_account=account, counter_account=expense, entry_date=txn2.txn_date, memo='Reject', amount=txn2.amount); e3 = await create_anchored_match_entry(db, user_id=test_user.id, bank_account=account, counter_account=expense, entry_date=txn3.txn_date, memo='Batch', amount=txn3.amount)
    m_accept = create_test_match(db, txn1, journal_entry_ids=[str(e1.id)], match_score=85); m_reject = create_test_match(db, txn2, journal_entry_ids=[str(e2.id)], match_score=75); m_batch = create_test_match(db, txn3, journal_entry_ids=[str(e3.id)], match_score=90); db.add_all([m_accept, m_reject, m_batch]); await db.commit()
    accepted = await reconciliation_router.accept_match(match_id=str(m_accept.id), db=db, user_id=test_user.id); rejected = await reconciliation_router.reject_match(match_id=str(m_reject.id), db=db, user_id=test_user.id); batch = await reconciliation_router.batch_update_matches(payload=ReconciliationMatchBatchRequest(action='accept', match_ids=[m_batch.id]), db=db, user_id=test_user.id); assert accepted.status == ReconciliationStatusEnum.ACCEPTED; assert rejected.status == ReconciliationStatusEnum.REJECTED; assert batch.approved_count == 1
